__mods['geo'] = function()
-- Geography on 32-bit numbers: positions are global pixels at a zoom (integers; 256 << 19 still fits),
-- degrees are integers in 1e-7 degrees, and floats (single precision on the device) only ever scale
-- small differences from an anchor, so nothing drifts at zoom 19.
local G = {}

local R = math.pi / 180

function G.tile_px(z) return 256 << z end

local function make_anchor(z, cx, cy, lon7, lat7)
  local W = G.tile_px(z)
  local lat = lat7 / 1e7
  local c = math.cos(lat * R)
  local k = W / 3600000000                     -- pixels per 1e-7 degree of longitude
  return {
    z = z, cx = cx, cy = cy, lon7 = lon7, lat7 = lat7,
    kx = k, ky = k / c,
    ky2 = k / c * math.tan(lat * R) * R * 1e-7 / 2,   -- the second-order term per (1e-7 degree)^2
  }
end

-- the view's anchor: its global pixel and its position, with the scale for differences around it
-- (second order in latitude, so a point 2 km away is still within a pixel at zoom 19). Its lon7 and
-- lat7 come from single-precision maths: fine for showing a point's coordinates, not for placing
-- things on the map (use anchor_ll for those, once per zoom).
function G.anchor(z, cx, cy)
  local W = G.tile_px(z)
  local lon = cx / W * 360 - 180
  local lat = (2 * math.atan(math.exp(math.pi * (1 - 2 * cy / W))) - math.pi / 2) / R   -- Lua has no sinh
  return make_anchor(z, cx, cy, math.floor(lon * 1e7 + 0.5), math.floor(lat * 1e7 + 0.5))
end

-- an anchor at a known position (a route's first point, a marker): its pixel from lonlat_px, so the
-- points around it land where the tiles are, and the same on every pan
function G.anchor_ll(z, lon7, lat7)
  local x, y = G.lonlat_px(z, lon7, lat7)
  return make_anchor(z, x, y, lon7, lat7)
end

-- -> global pixels (integers) of a point near the anchor. The offsets are rounded first and added as
-- integers: a float sum near 2^27 would snap to 8 px on the device.
function G.to_px(A, lon7, lat7)
  local dl = lat7 - A.lat7
  local dx = math.floor((lon7 - A.lon7) * A.kx + 0.5)
  local dy = math.floor(dl * A.ky + dl * A.ky2 * dl + 0.5)     -- dl * dl would wrap in 32 bits
  return A.cx + dx, A.cy - dy
end

-- -> lon7, lat7 of a global pixel near the anchor
function G.from_px(A, x, y)
  local lon7 = A.lon7 + math.floor((x - A.cx) / A.kx + 0.5)
  local d = (A.cy - y) / A.ky                    -- first guess, then one Newton step for the square term
  d = d - (d * A.ky + d * A.ky2 * d - (A.cy - y)) / (A.ky + 2 * d * A.ky2)
  return lon7, A.lat7 + math.floor(d + 0.5)
end

-- -> metres, pixels: the round length (1, 2 or 5 x 10^n) whose bar is nearest 90 px long
function G.scale_bar(z, lat7)
  local mpp = 156543.03392 * math.cos(lat7 / 1e7 * R) / (1 << z)
  local bm, bp
  for e = 0, 7 do
    for _, f in ipairs({ 1, 2, 5 }) do
      local m = f * 10 ^ e
      local px = m / mpp
      if not bp or math.abs(px - 90) < math.abs(bp - 90) then bm, bp = m, px end
    end
  end
  return math.floor(bm + 0.5), math.floor(bp + 0.5)
end

-- "12.345" -> 123450000 (1e-7 degrees), exactly, from the digits
local function dec7(s)
  local sign, int, frac = s:match('^%s*([%-+]?)(%d*)%.?(%d*)%s*$')
  if not sign or (int == '' and frac == '') then return nil end
  frac = (frac .. '0000000'):sub(1, 7)
  local v = (tonumber(int) or 0) * 10000000 + tonumber(frac)
  return sign == '-' and -v or v
end
G.dec7 = dec7
-- 41°0'29.5"N -> 1e-7 degrees
local function dms7(s)
  local d, m, sec, h = s:match('^%s*(%d+)%s*°%s*(%d*)%s*[\'′]?%s*([%d%.]*)%s*["″]?%s*([NSEWnsew]?)%s*$')
  if not d then return nil end
  local secm = 0
  if sec ~= '' then
    local si, sf = sec:match('^(%d*)%.?(%d*)$')
    if not si then return nil end
    secm = (tonumber(si) or 0) * 1000 + tonumber(((sf or '') .. '000'):sub(1, 3))
  end
  local v = tonumber(d) * 10000000 + ((tonumber(m) or 0) * 60000 + secm) * 25 // 9
  h = h:upper()
  return (h == 'S' or h == 'W') and -v or v, h
end

-- "41.0082, 28.9784", "41.0082 28.9784" or 41°0'29.5"N 28°58'42.2"E -> lat7, lon7 | nil, reason
function G.parse_coords(s)
  s = tostring(s or '')
  local a, b = s:match('^%s*([%-+]?[%d%.]+)%s*[,;%s]%s*([%-+]?[%d%.]+)%s*$')
  local lat, lon
  if a then
    lat, lon = dec7(a), dec7(b)
  else
    local p, q = s:match('^(.-[NSns])[%s,;]+(.-[EWew])%s*$')
    if p then lat, lon = dms7(p), dms7(q) end
  end
  if not lat or not lon then return nil, 'Type a position like 41.0082, 28.9784' end
  if lat < -900000000 or lat > 900000000 or lon < -1800000000 or lon > 1800000000 then
    return nil, 'Latitude goes to 90 and longitude to 180'
  end
  return lat, lon
end

-- global pixel of a position at zoom z (for a jump: the new view's anchor comes from here)
-- x exactly, by long division on 32-bit integers (q in 4e-7 degrees, 0 .. 9e8: 2 * q still fits);
-- y in single precision (a few pixels off at zoom 19, the same for everything placed with it)
local MAXLAT7 = 850511287
function G.lonlat_px(z, lon7, lat7)
  local D = 900000000
  local q = lon7 // 4 + 450000000
  local x, r = q // D, q % D
  for _ = 1, z + 8 do
    r = r * 2
    x = x * 2
    if r >= D then x = x + 1; r = r - D end
  end
  lat7 = math.max(-MAXLAT7, math.min(MAXLAT7, lat7))   -- the poles are outside Web Mercator
  local lat = lat7 / 1e7 * R
  local y = (1 - math.log(math.tan(lat) + 1 / math.cos(lat)) / math.pi) / 2 * G.tile_px(z)
  return x, math.floor(y)
end

-- a decimal position for showing: 41.00820, 28.97840
function G.fmt(lat7, lon7)
  local function f(v)
    local s = v < 0 and '-' or ''
    local u = (math.abs(v) + 50) // 100            -- 1e-5 degrees, rounded
    return string.format('%s%d.%05d', s, u // 100000, u % 100000)
  end
  return f(lat7) .. ', ' .. f(lon7)
end

return G
end

__mods['gpx'] = function()
-- GPX routes (from a phone app, Komoot, Strava, a hiking site): track and route points read without
-- an XML library, thinned per zoom so a long track still draws fast, and measured.
local geo = require('geo')

local X = {}

-- text -> { name, points = { {lat7, lon7}, ... } } | nil, reason
function X.parse(text)
  text = tostring(text or '')
  local pts = {}
  for tag in text:gmatch('<%s*[%w:]*[rt][rt][ke]pt%s([^>]*)>') do
    local lat = tag:match('lat%s*=%s*["\']([^"\']+)["\']')
    local lon = tag:match('lon%s*=%s*["\']([^"\']+)["\']')
    local la, lo = lat and geo.dec7(lat), lon and geo.dec7(lon)
    if la and lo then pts[#pts + 1] = { lat7 = la, lon7 = lo } end
  end
  if #pts == 0 then return nil, 'no track or route points in this file' end
  -- street names to write beside the route (our tool's GPX): <wpt ...><name>..</name><type>street</type></wpt>
  local labels = {}
  for attrs, body in text:gmatch('<%s*[%w:]*wpt%s([^>]*)>(.-)</%s*[%w:]*wpt%s*>') do
    local ty = body:match('<%s*type%s*>%s*([^<]-)%s*</')
    local nm = body:match('<%s*name%s*>%s*([^<]-)%s*</')
    local lat = attrs:match('lat%s*=%s*["\']([^"\']+)')
    local lon = attrs:match('lon%s*=%s*["\']([^"\']+)')
    local la, lo = lat and geo.dec7(lat), lon and geo.dec7(lon)
    if ty == 'street' and nm and nm ~= '' and la and lo then labels[#labels + 1] = { name = X.unescape(nm), lat7 = la, lon7 = lo } end
  end
  -- the route's own name: the metadata's or the track's, not a waypoint's
  local body = text:gsub('<%s*[%w:]*wpt%s.-</%s*[%w:]*wpt%s*>', '')
  local name = body:match('<%s*name%s*>%s*([^<]-)%s*</%s*name%s*>')
  if name then name = X.unescape((name:gsub('<!%[CDATA%[(.-)%]%]>', '%1'))) end
  return { name = name ~= '' and name or nil, points = pts, labels = labels }
end

function X.unescape(s)
  return (s:gsub('&lt;', '<'):gsub('&gt;', '>'):gsub('&quot;', '"'):gsub('&#39;', "'"):gsub('&amp;', '&'))
end

-- the points at least 2 px apart at zoom z (the first and the last kept)
function X.thin(points, z)
  local step = 2 * 3600000000 / geo.tile_px(z)      -- 2 px in 1e-7 degrees (of longitude)
  local out = {}
  local last
  for i, p in ipairs(points) do
    if not last or i == #points or math.abs(p.lon7 - last.lon7) >= step or math.abs(p.lat7 - last.lat7) >= step then
      out[#out + 1] = p
      last = p
    end
  end
  return out
end

-- metres along the points (haversine, step by step)
function X.length_m(points)
  local R = math.pi / 180 / 1e7
  local m = 0
  for i = 2, #points do
    local a, b = points[i - 1], points[i]
    local p1, p2 = a.lat7 * R, b.lat7 * R
    local dp, dl = (b.lat7 - a.lat7) * R, (b.lon7 - a.lon7) * R
    local h = math.sin(dp / 2) ^ 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ^ 2
    m = m + 2 * 6371000 * math.asin(math.min(1, math.sqrt(h)))
  end
  return math.floor(m + 0.5)
end

function X.length_text(m)
  if m < 1000 then return m .. ' m' end
  local d = (m + 50) // 100
  return (d // 10) .. '.' .. (d % 10) .. ' km'
end

return X
end

__mods['labels'] = function()
-- Street names beside a route: which names (a GPX's street waypoints, or the street entries of the
-- packs' name index near the route), and where at a zoom (on the route, turned along it, moved to one
-- side, not too close to another).
local names = require('names')
local geo = require('geo')

local L = {}

local M7 = 0.011132                 -- metres per 1e-7 degree of latitude

-- the direction (dx, dy) in screen pixels -> degrees clockwise, turned to read left to right
function L.angle(dx, dy)
  local d = math.atan(dy, dx) * 180 / math.pi
  if d > 90 then d = d - 180 elseif d < -90 then d = d + 180 end
  return math.floor(d + 0.5)
end

-- metres from point p to the segment a-b (all {lat7, lon7}, near each other), cos = cos(latitude)
local function dist_m(p, a, b, cos)
  local ax, ay = (a.lon7 - p.lon7) * M7 * cos, (a.lat7 - p.lat7) * M7
  local bx, by = (b.lon7 - p.lon7) * M7 * cos, (b.lat7 - p.lat7) * M7
  local dx, dy = bx - ax, by - ay
  local l2 = dx * dx + dy * dy
  local t = l2 > 0 and math.max(0, math.min(1, -(ax * dx + ay * dy) / l2)) or 0
  local x, y = ax + t * dx, ay + t * dy
  return math.sqrt(x * x + y * y)
end

-- the street entries (kind 6) of the packs the route crosses, within max_m metres of it; a name once
-- per 300 m. Reads each such pack's whole name index once (when a route opens).
function L.from_index(packs, points, max_m)
  if #points < 2 then return {} end
  local w, s, e, n = points[1].lon7, points[1].lat7, points[1].lon7, points[1].lat7
  for _, p in ipairs(points) do
    if p.lon7 < w then w = p.lon7 end
    if p.lon7 > e then e = p.lon7 end
    if p.lat7 < s then s = p.lat7 end
    if p.lat7 > n then n = p.lat7 end
  end
  local cos = math.cos((s / 2 + n / 2) / 1e7 * math.pi / 180)
  local my = math.floor(max_m / M7) + 1
  local mx = math.floor(max_m / M7 / cos) + 1
  local out = {}
  for _, pk in ipairs(packs) do
    local b = pk.meta.bounds or {}
    local bw, bs, be, bn = (tonumber(b[1]) or -180) * 1e7, (tonumber(b[2]) or -90) * 1e7, (tonumber(b[3]) or 180) * 1e7, (tonumber(b[4]) or 90) * 1e7
    if not (be < w - mx or bw > e + mx or bn < s - my or bs > n + my) then
      for _, bl in ipairs(pk.dir or {}) do
        for _, en in ipairs(names.entries(pk, bl)) do
          if en.kind == 6 and en.lon7 >= w - mx and en.lon7 <= e + mx and en.lat7 >= s - my and en.lat7 <= n + my then
            local best = math.huge
            for i = 2, #points do
              local d = dist_m(en, points[i - 1], points[i], cos)
              if d < best then best = d end
            end
            if best <= max_m then
              local dup = false
              for _, o in ipairs(out) do
                if o.name == en.name and dist_m(o, en, en, cos) < 300 then dup = true; break end
              end
              if not dup then out[#out + 1] = { name = en.name, lat7 = en.lat7, lon7 = en.lon7 } end
            end
          end
        end
      end
    end
  end
  return out
end

-- labels at zoom z on the route's global pixels px {x1, y1, ...}: level boxes beside the route (the
-- reader turns no pictures): { {idx, x, y, w, h} }, x and y the box's top left in global pixels. Beside
-- a north-south piece the box is to its right; beside an east-west piece, above it. A box that would
-- overlap one already placed is left out, and so is a name already placed within SAME px. measure(name) -> width; lh: the line height.
local PAD, SIDE = 8, 12
local SAME = 700                  -- the same name at most once in this many pixels (about a screen)
function L.place(px, labels, z, measure, lh)
  local out = {}
  local n = #px // 2
  if n < 2 then return out end
  for li, lb in ipairs(labels) do
    local lx, ly = geo.lonlat_px(z, lb.lon7, lb.lat7)
    -- the nearest piece and where on it; only differences go through floats
    local best, bt, bax, bay, bdx, bdy
    for k = 1, n - 1 do
      local ax, ay = px[2 * k - 1], px[2 * k]
      local dx, dy = px[2 * k + 1] - ax, px[2 * k + 2] - ay
      local l2 = dx * dx + dy * dy
      if l2 > 0 then
        local ox, oy = lx - ax, ly - ay
        local t = math.max(0, math.min(1, (ox * dx + oy * dy) / l2))
        local d = (t * dx - ox) ^ 2 + (t * dy - oy) ^ 2
        if not best or d < best then best, bt, bax, bay, bdx, bdy = d, t, ax, ay, dx, dy end
      end
    end
    if best then
      local qx, qy = bax + math.floor(bt * bdx + 0.5), bay + math.floor(bt * bdy + 0.5)
      local w, h = measure(lb.name) + 2 * PAD, lh + 4
      local x, y
      if math.abs(bdx) >= math.abs(bdy) then x, y = qx - w // 2, qy - SIDE - h     -- above
      else x, y = qx + SIDE, qy - h // 2 end                                       -- to the right
      local clash = false
      for _, o in ipairs(out) do
        if x < o.x + o.w + 10 and o.x < x + w + 10 and y < o.y + o.h + 10 and o.y < y + h + 10 then clash = true; break end
        if labels[o.idx].name == lb.name and math.abs(o.x - x) < SAME and math.abs(o.y - y) < SAME then clash = true; break end
      end
      if not clash then out[#out + 1] = { idx = li, x = x, y = y, w = w, h = h } end
    end
  end
  return out
end

return L
end

__mods['names'] = function()
-- Search by name: each pack's name index is sorted by a folded key (src/fold.lua, the tool's rule)
-- in blocks of at most 4 KB, with a directory read at open; a prefix search costs a binary search of
-- the directory and one or two block reads per pack.
local fold = require('fold').fold
local pack = require('pack')

local N = {}

N.ZOOM = { 12, 13, 14, 14, 15, 17, 16, 15, 15, 13, 17 }   -- by kind: city .. POI
N.KIND = { 'city', 'town', 'village', 'district', 'place', 'street', 'station', 'peak', 'park', 'water', 'place' }

local function starts(s, q) return s:sub(1, #q) == q end

function N.entries(p, bl)
  local out = {}
  local b = pack.span(p.name, bl.off, bl.len)
  if not b then return out end
  local i = 1
  for _ = 1, bl.count do
    local kl = b:byte(i); if not kl then break end
    local key = b:sub(i + 1, i + kl); i = i + 1 + kl
    local nl = b:byte(i)
    local name = b:sub(i + 1, i + nl); i = i + 1 + nl
    local kind = b:byte(i); i = i + 1
    local lon7, lat7 = string.unpack('<i4i4', b, i); i = i + 8
    out[#out + 1] = { key = key, name = name, kind = kind, lon7 = lon7, lat7 = lat7, pack = p }
  end
  return out
end

-- the matches of the folded prefix q in one pack
local function in_pack(p, q, limit, out)
  local dir = p.dir
  if not dir or #dir == 0 then return end
  local lo, hi, at = 1, #dir, 1
  while lo <= hi do                                -- the last block whose first key is < q: a run of
    local m = (lo + hi) // 2                       -- keys equal to q may start in it
    if dir[m].first < q then at = m; lo = m + 1 else hi = m - 1 end
  end
  local n = 0
  for b = at, #dir do                              -- on while blocks can still hold matches
    if b > at and not starts(dir[b].first, q) then break end
    for _, e in ipairs(N.entries(p, dir[b])) do
      if starts(e.key, q) then out[#out + 1] = e; n = n + 1; if n >= limit then return end end
    end
  end
end

-- -> matches from every pack, sorted by name; the same place in two packs once
function N.search(packs, query, limit)
  limit = limit or 30
  local q = fold(query)
  local all = {}
  if q == '' then return all end
  for _, p in ipairs(packs) do in_pack(p, q, limit, all) end
  table.sort(all, function(a, b) if a.key ~= b.key then return a.key < b.key end return a.pack.area < b.pack.area end)
  local out = {}
  for _, e in ipairs(all) do
    local dup = false
    for _, o in ipairs(out) do
      if o.name == e.name and o.kind == e.kind and math.abs(o.lon7 - e.lon7) < 30000 and math.abs(o.lat7 - e.lat7) < 30000 then dup = true; break end
    end
    if not dup then out[#out + 1] = e end
    if #out >= limit then break end
  end
  return out
end

return N
end

__mods['near'] = function()
-- The name of what is held on the map, for the long press box: a street whose thin line is hard to
-- hold exactly, a peak, a lake. A pack's nearest-name section (site/tools/offlinemap/near.js) holds
-- its named lines (streets, paths, rivers), points (places, stations, peaks) and areas (lakes, parks)
-- in buckets of one tile at zoom zb, as pixels at zoom zb + 5 from the bucket's corner, each with the
-- zoom the map first draws it at: only what the map shows at the view's zoom is named.
--   nearest: a point under the finger (HIT px) if any, else, where the map draws streets, the nearest
--            line, else the nearest point, up to MAX_PX away on the screen. Rings of buckets are read
--            outwards until nothing unread can be nearer. Only the packs that hold the point are asked:
--            a pack without the section (an old one) is not filled in from another pack's names.
--   area:    the area the point is inside.
local pack = require('pack')
local geo = require('geo')

local M = {}

local UNIT = 8192
local MAX_READS = 60            -- bucket reads a long press may make (an empty corner of a big pack)
M.HIT = 32                      -- pixels: a point (a peak, a station, a place label) this near is the one held
M.LINES_FROM = 12               -- the zoom from which the map draws streets
M.MAX_PX = 240                  -- pixels at the view's zoom: anything farther is not near (half the screen's width)

local u16 = function(s, i) return (string.unpack('<I2', s, i)) end
local u32 = function(s, i) return (string.unpack('<I4', s, i)) end

-- the section's head, read once a pack; false when the pack has none (made before 2026-11-16)
local function head(p)
  if p.near ~= nil then return p.near end
  p.near = false
  if (p.near_len or 0) > 16 then
    local h = pack.span(p.name, p.near_off, 16)
    if h and #h == 16 then
      p.near = { zb = h:byte(1), x0 = u32(h, 5), y0 = u32(h, 9), nx = u16(h, 13), ny = u16(h, 15), rows = {} }
    end
  end
  return p.near
end

-- the bytes of bucket (bx, by), or nil when it is empty or outside; a row of the index is read once
local function bucket(p, h, bx, by)
  if bx < h.x0 or by < h.y0 or bx >= h.x0 + h.nx or by >= h.y0 + h.ny then return nil end
  local row = h.rows[by]
  if row == nil then
    row = pack.span(p.name, p.near_off + 16 + 8 * (by - h.y0) * h.nx, 8 * h.nx) or false
    h.rows[by] = row
  end
  if not row then return nil end
  local i = 1 + 8 * (bx - h.x0)
  local off, len = u32(row, i), u32(row, i + 4)
  if len == 0 then return nil end
  return pack.span(p.name, p.near_off + off, len)
end

-- each record of bucket b drawn at z: fn(shape, kind, name, p0 (the first point's index in b), n)
local function records(b, z, fn)
  local i, n = 1, #b
  while i + 5 <= n do
    local kind, from, shape, nl = b:byte(i, i + 3)
    local np = u16(b, i + 4 + nl)
    local p0 = i + 6 + nl
    if z >= from and np > 0 then fn(shape, kind, b:sub(i + 4, i + 3 + nl), p0, np) end
    i = p0 + 4 * np
  end
end

-- the records of bucket b drawn at z, measured from (qx, qy) (units from the bucket's corner): the
-- nearest line in near.line, the nearest point in near.point, as { d (squared units), name, kind }
local function scan(b, qx, qy, z, near)
  records(b, z, function(shape, kind, name, p0, np)
    if shape == 2 then return end
    local ax, ay = string.unpack('<i2i2', b, p0)
    local d = (ax - qx) ^ 2 + (ay - qy) ^ 2
    for k = 1, np - 1 do
      local bx, by = string.unpack('<i2i2', b, p0 + 4 * k)
      local dx, dy = bx - ax, by - ay
      local l2 = dx * dx + dy * dy
      if l2 > 0 then
        local t = math.max(0, math.min(1, ((qx - ax) * dx + (qy - ay) * dy) / l2))
        local e = (ax + t * dx - qx) ^ 2 + (ay + t * dy - qy) ^ 2
        if e < d then d = e end
      end
      ax, ay = bx, by
    end
    local best = shape == 1 and near.line or near.point
    if not best.d or d < best.d then best.d, best.name, best.kind = d, name, kind end
  end)
end

-- the packs with the section that hold the point, with the point in each one's units
local function places(packs, lon7, lat7)
  local todo = {}
  for _, pk in ipairs(packs) do
    local h = head(pk)
    local zz = h and h.zb + 5
    local x, y = 0, 0
    if h then x, y = geo.lonlat_px(zz, lon7, lat7) end
    local cx, cy = x // UNIT, y // UNIT
    if h and cx >= h.x0 and cy >= h.y0 and cx < h.x0 + h.nx and cy < h.y0 + h.ny then
      local x1, y1 = h.x0 + h.nx - 1, h.y0 + h.ny - 1
      todo[#todo + 1] = {
        p = pk, h = h, x = x, y = y, cx = cx, cy = cy, zz = zz,
        mpu = 40075016.686 * math.cos(lat7 / 1e7 * math.pi / 180) / (256 << zz),   -- metres a unit
        edge = math.min(x - cx * UNIT, (cx + 1) * UNIT - x, y - cy * UNIT, (cy + 1) * UNIT - y),
        r1 = math.max(cx - h.x0, x1 - cx, cy - h.y0, y1 - cy),                     -- the last ring in the grid
      }
    end
  end
  return todo
end

-- -> { name, kind, m (metres) } of what is held at zoom z, or nil
function M.nearest(packs, lon7, lat7, z)
  pcall(function() ctx.budget:extend() end)
  local lines = z >= M.LINES_FROM
  local line, point, reads = nil, nil, 0
  for _, t in ipairs(places(packs, lon7, lat7)) do
    local h, found = t.h, { line = {}, point = {} }
    local hit_u = M.HIT * (2.0 ^ (t.zz - z))       -- HIT pixels at z, in units
    local max_u = M.MAX_PX * (2.0 ^ (t.zz - z))    -- MAX_PX pixels at z
    for r = 0, t.r1 do
      -- what lies only in ring r or beyond is at least this far
      local least = r > 0 and t.edge + (r - 1) * UNIT or 0
      local want = lines and found.line.d or found.point.d
      if want and want <= least * least and least >= hit_u then break end
      local sofar = lines and line or point
      if sofar and least * t.mpu >= sofar.m and least >= hit_u then break end
      if reads >= MAX_READS or least > max_u then break end
      for by = math.max(h.y0, t.cy - r), math.min(h.y0 + h.ny - 1, t.cy + r) do
        local all = by == t.cy - r or by == t.cy + r
        local bx = math.max(h.x0, t.cx - r)
        local last = math.min(h.x0 + h.nx - 1, t.cx + r)
        while bx <= last do
          if all or bx == t.cx - r or bx == t.cx + r then
            local b = bucket(t.p, h, bx, by)
            if b then
              reads = reads + 1
              scan(b, t.x - bx * UNIT, t.y - by * UNIT, z, found)
            end
          end
          if all or bx == t.cx + r then bx = bx + 1 else bx = math.max(bx + 1, t.cx + r) end
        end
      end
    end
    local function keep(f, cur)
      if not f.d or f.d > max_u * max_u then return cur end
      local m = math.sqrt(f.d) * t.mpu
      if not cur or m < cur.m then return { name = f.name, kind = f.kind, m = m, hit = math.sqrt(f.d) <= hit_u } end
      return cur
    end
    line, point = keep(found.line, line), keep(found.point, point)
  end
  if point and point.hit then return point end
  if lines and line then return line end
  return point or line
end

-- -> the name of the area (a lake, a park) the point is inside at zoom z, or nil; the smallest one
function M.area(packs, lon7, lat7, z)
  local best, size
  for _, t in ipairs(places(packs, lon7, lat7)) do
    local b = bucket(t.p, t.h, t.cx, t.cy)
    if b then
      local qx, qy = t.x - t.cx * UNIT, t.y - t.cy * UNIT
      records(b, z, function(shape, _kind, name, p0, np)
        if shape ~= 2 or np < 3 then return end
        local inside, x0, y0, x1, y1 = false, math.huge, math.huge, -math.huge, -math.huge
        local jx, jy = string.unpack('<i2i2', b, p0 + 4 * (np - 1))
        for k = 0, np - 1 do
          local ix, iy = string.unpack('<i2i2', b, p0 + 4 * k)
          if (iy > qy) ~= (jy > qy) and qx < (jx - ix) * (qy - iy) / (jy - iy) + ix then inside = not inside end
          if ix < x0 then x0 = ix end
          if ix > x1 then x1 = ix end
          if iy < y0 then y0 = iy end
          if iy > y1 then y1 = iy end
          jx, jy = ix, iy
        end
        local s = (x1 - x0) * (y1 - y0) * t.mpu * t.mpu
        if inside and (not size or s < size) then best, size = name, s end
      end)
    end
  end
  return best
end

local function dist(m)
  return m < 1000 and string.format('%d m', math.floor(m + 0.5))
    or m < 10000 and string.format('%.1f km', m / 1000)
    or string.format('%d km', math.floor(m / 1000 + 0.5))
end

-- the box's line: Nearest: Moda Caddesi, 40 m
function M.text(r) return 'Nearest: ' .. r.name .. ', ' .. dist(r.m) end

-- the box's lines for a point at zoom z: In: <area>, Nearest: <name>, <distance>. Inside an area,
-- a nearest name farther than AREA_NEAR pixels is left out: the area is what was held.
M.AREA_NEAR = 3 * M.HIT
function M.lines(packs, lon7, lat7, z)
  local out = {}
  local ok, a = pcall(M.area, packs, lon7, lat7, z)
  if ok and a then out[#out + 1] = 'In: ' .. a end
  local ok2, r = pcall(M.nearest, packs, lon7, lat7, z)
  if ok2 and r then
    local mpp = 156543.03392 * math.cos(lat7 / 1e7 * math.pi / 180) / (1 << z)   -- metres a pixel at z
    if not (ok and a) or r.m <= M.AREA_NEAR * mpp then out[#out + 1] = M.text(r) end
  end
  return out
end

return M
end

__mods['pack'] = function()
-- Reading a map pack (format v1, written by site/tools/offlinemap/pack.js) with offset reads of at
-- most 64 KB: the header, the meta, the zoom table and the name directory at open; a row's index and
-- its tiles (stored together) on demand.
local P = {}
P.__index = P

local MAX = 65536

-- len bytes at off, in reads of at most 64 KB
local function span(name, off, len)
  if len <= 0 then return '' end
  local parts = {}
  local done = 0
  while done < len do
    local n = math.min(MAX, len - done)
    local ok, b = pcall(function() return ctx.files:read(name, off + done, n) end)
    if not ok or type(b) ~= 'string' or #b == 0 then return nil end
    parts[#parts + 1] = b
    done = done + #b
  end
  return table.concat(parts)
end
P.span = span

local u16 = function(s, i) return string.unpack('<I2', s, i) end
local u32 = function(s, i) return string.unpack('<I4', s, i) end

-- -> the pack, or nil and a reason
function P.open(name)
  local h = span(name, 0, 64)
  if not h or #h < 64 or h:sub(1, 8) ~= 'XTMAP1\0\0' or u16(h, 9) ~= 1 then return nil, 'not a map pack' end
  if h:byte(12) ~= 2 or u16(h, 13) ~= 256 then return nil, 'an unknown tile format' end
  local nlev = h:byte(11)
  local meta_off, meta_len, zoom_off = u32(h, 17), u32(h, 21), u32(h, 25)
  local names_off, names_len = u32(h, 29), u32(h, 33)
  local mj = span(name, meta_off, meta_len)
  local okj, meta = pcall(function() return ctx.json:decode(mj) end)
  if not okj or type(meta) ~= 'table' then return nil, 'a damaged map pack' end
  local zt = span(name, zoom_off, 20 * nlev)
  if not zt then return nil, 'a damaged map pack' end
  local self = setmetatable({ name = name, meta = meta, levels = {}, zmin = 99, zmax = -1,
    near_off = u32(h, 37), near_len = u32(h, 41) }, P)   -- the nearest-name section (src/near.lua), 0 in old packs
  local deepest
  for i = 0, nlev - 1 do
    local o = 1 + 20 * i
    local z = zt:byte(o)
    local l = { z = z, x0 = u32(zt, o + 4), y0 = u32(zt, o + 8), nx = u16(zt, o + 12), ny = u16(zt, o + 14), index = u32(zt, o + 16) }
    self.levels[z] = l
    if z < self.zmin then self.zmin = z end
    if z > self.zmax then self.zmax = z; deepest = l end
  end
  -- size of the area, as tiles at zoom 19 (a float: only compared): the smallest pack is the most detailed
  self.area = deepest and deepest.nx * deepest.ny * (4.0 ^ (19 - deepest.z)) or 0
  self.made = tostring(meta.made or '')
  local oks, sz = pcall(function() return ctx.files:size(name) end)
  self.file_size = oks and tonumber(sz) or 0
  -- the name directory: { off (absolute), len, count, first }
  self.dir = {}
  if names_len > 0 then
    local d = span(name, names_off, math.min(names_len, MAX))
    if d and #d >= 4 then
      local nb = u32(d, 1)
      local p = 5
      for _ = 1, nb do
        if p + 8 > #d then break end
        local klen = d:byte(p + 8)
        self.dir[#self.dir + 1] = { off = names_off + u32(d, p), len = u16(d, p + 4), count = u16(d, p + 6), first = d:sub(p + 9, p + 8 + klen) }
        p = p + 9 + klen
      end
    end
  end
  return self
end

-- does this pack have level z, and tile (x, y) inside its range?
function P:has(z, x, y)
  local l = self.levels[z]
  return l ~= nil and x >= l.x0 and y >= l.y0 and x < l.x0 + l.nx and y < l.y0 + l.ny
end

-- tiles xa..xb of row y at level z -> { [x] = zlib bytes | false (empty paper) }; tiles outside the
-- range are left out
function P:read_row(z, y, xa, xb)
  local l = self.levels[z]
  local out = {}
  if not l or y < l.y0 or y >= l.y0 + l.ny then return out end
  xa, xb = math.max(xa, l.x0), math.min(xb, l.x0 + l.nx - 1)
  if xa > xb then return out end
  local n = xb - xa + 1
  local idx = span(self.name, l.index + 8 * ((y - l.y0) * l.nx + (xa - l.x0)), 8 * n)
  if not idx then return out end
  local first, last
  local ents = {}
  for i = 0, n - 1 do
    local off, len = u32(idx, 1 + 8 * i), u32(idx, 5 + 8 * i)
    ents[i] = { off, len }
    if len > 0 then
      if not first or off < first then first = off end
      if not last or off + len > last then last = off + len end
    end
  end
  local data = first and span(self.name, first, last - first)
  for i = 0, n - 1 do
    local off, len = ents[i][1], ents[i][2]
    if len == 0 or not data then out[xa + i] = false
    else out[xa + i] = data:sub(off - first + 1, off - first + len) end
  end
  return out
end

return P
end

__mods['view'] = function()
-- The map view, put together in an offscreen layer: tiles are read a row at a time, unzipped,
-- decoded at most 6 at a time and drawn in one layer:draw, and freed only after that draw returns
-- (a picture freed inside the draw is drawn blank on the device). A pan copies the old layer shifted
-- into the spare one and draws only the tiles that came into view. on_draw only shows the layer.
local choose = require('choose')

local V = {}
V.__index = V

local BATCH = 6
local T = 256

function V.new(c, w, h)
  local self = setmetatable({ w = w, h = h, z = 14, cx = 0, cy = 0, packs = {}, edge = false, missing = 0,
    overlay = nil }, V)
  self.layer = c.layers:create(w, h)
  self.spare = c.layers:create(w, h)
  return self
end

function V:left() return self.cx - self.w // 2 end
function V:top() return self.cy - self.h // 2 end

-- the tiles touching the rectangle (global pixels) x0..x1, y0..y1
local function tiles_in(x0, y0, x1, y1)
  return x0 >> 8, y0 >> 8, x1 >> 8, y1 >> 8
end

local function extend() pcall(function() ctx.budget:extend() end) end

-- draw the tiles of the rectangles (global pixels) into `target`; `first` runs at the start of the
-- first layer:draw (clear, or the shifted old layer)
function V:paint(target, rects, first)
  extend()                                         -- before the reads, too
  local z, left, top = self.z, self:left(), self:top()
  local seen, jobs, frames = {}, {}, {}
  for _, r in ipairs(rects) do
    local tx0, ty0, tx1, ty1 = tiles_in(r[1], r[2], r[3], r[4])
    for ty = ty0, ty1 do
      -- per pack, the run of tiles it draws in this row: one read of the index, one of the pictures
      local runs = {}
      for tx = tx0, tx1 do
        local key = tx .. ',' .. ty
        if not seen[key] then
          seen[key] = true
          local p = choose.pick(self.packs, z, tx, ty)
          if p then
            local run = runs[p]
            if not run then run = { p = p, a = tx, b = tx, want = {} }; runs[p] = run end
            if tx < run.a then run.a = tx end
            if tx > run.b then run.b = tx end
            run.want[#run.want + 1] = tx
          else
            frames[#frames + 1] = { tx * T - left, ty * T - top }
          end
        end
      end
      for _, run in pairs(runs) do
        local row = run.p:read_row(z, ty, run.a, run.b)
        for _, tx in ipairs(run.want) do
          local b = row[tx]
          if b then jobs[#jobs + 1] = { b, tx * T - left, ty * T - top } end
        end
      end
    end
  end
  extend()
  local i, started = 1, false
  repeat
    local batch = {}
    while #batch < BATCH and i <= #jobs do
      local j = jobs[i]
      i = i + 1
      local okz, bmp = pcall(function() return ctx.zlib:decompress(j[1]) end)
      local okd, im = false, nil
      if okz and bmp then okd, im = pcall(function() return ctx.image:decode(bmp) end) end
      if okd and im then batch[#batch + 1] = { im, j[2], j[3] } end
    end
    local last = i > #jobs
    target:draw(function(g)
      if not started and first then first(g) end
      for _, b in ipairs(batch) do g:image(b[1], b[2], b[3]) end
      if last then
        for _, f in ipairs(frames) do                 -- no pack here: a faint dotted frame
          for k = 0, T - 8, 8 do
            g:line(f[1] + k, f[2], f[1] + k + 3, f[2]); g:line(f[1] + k, f[2] + T - 1, f[1] + k + 3, f[2] + T - 1)
            g:line(f[1], f[2] + k, f[1], f[2] + k + 3); g:line(f[1] + T - 1, f[2] + k, f[1] + T - 1, f[2] + k + 3)
          end
        end
        if self.overlay then self.overlay(g, left, top) end
      end
    end)
    started = true
    for _, b in ipairs(batch) do pcall(function() b[1]:release() end) end   -- after the draw returned
  until last
end

-- how many visible tiles no pack has
function V:count_missing()
  local left, top = self:left(), self:top()
  local tx0, ty0, tx1, ty1 = tiles_in(left, top, left + self.w - 1, top + self.h - 1)
  local n = 0
  for ty = ty0, ty1 do
    for tx = tx0, tx1 do
      if not choose.pick(self.packs, self.z, tx, ty) then n = n + 1 end
    end
  end
  self.missing = n
  self.edge = n > 0
end

function V:set(z, cx, cy)
  self.z, self.cx, self.cy = z, cx, cy
  local left, top = self:left(), self:top()
  self:paint(self.layer, { { left, top, left + self.w - 1, top + self.h - 1 } }, function(g) g:clear(0) end)
  self:count_missing()
end

-- the redraw of the current view (after the overlay changed)
function V:refresh() self:set(self.z, self.cx, self.cy) end

function V:pan(dx, dy)
  if math.abs(dx) >= self.w or math.abs(dy) >= self.h then return self:set(self.z, self.cx + dx, self.cy + dy) end
  self.cx, self.cy = self.cx + dx, self.cy + dy
  local left, top = self:left(), self:top()
  local r = {}
  local x1, y1 = left + self.w - 1, top + self.h - 1
  if dx > 0 then r[#r + 1] = { x1 - dx + 1, top, x1, y1 } elseif dx < 0 then r[#r + 1] = { left, top, left - dx - 1, y1 } end
  if dy > 0 then r[#r + 1] = { left, y1 - dy + 1, x1, y1 } elseif dy < 0 then r[#r + 1] = { left, top, x1, top - dy - 1 } end
  local old = self.layer
  self:paint(self.spare, r, function(g) g:clear(0); g:image(old, -dx, -dy) end)
  self.layer, self.spare = self.spare, old
  self:count_missing()
end

-- one level in (dir 1) or out (-1), keeping the screen point (px, py) where it is
function V:zoom(dir, px, py)
  local gx, gy = self:left() + px, self:top() + py
  if dir > 0 then gx, gy = gx * 2, gy * 2 else gx, gy = gx // 2, gy // 2 end
  self:set(self.z + dir, gx - px + self.w // 2, gy - py + self.h // 2)
end

function V:draw(g, x, y) g:image(self.layer, x, y) end

function V:release()
  pcall(function() self.layer:release() end)
  pcall(function() self.spare:release() end)
end

return V
end

-- Offline Map: map packs made on the site's Tools page (AppFiles/offlinemap/*.map), shown without a
-- connection. The map screen: a header (pack, zoom, scale bar), the map, and - + Search Menu.
local geo = require('geo')
local fold = require('fold')
local pack = require('pack')
local choose = require('choose')
local view = require('view')
local names = require('names')
local gpx = require('gpx')
local labels = require('labels')
local near = require('near')

local TOOLS_URL = 'https://omer-faruq-xteink.github.io/touch-licorice-apps/tools/offlinemap/'
local HEAD, BAR = 34, 52
local MOVE = 20                 -- a finger that moved more than this is a drag
local MSG_MS = 3000

local W, H = 480, 800
local screen = 'map'            -- map | start | search | menu | bookmarks | routes | packs | about | coords
local packs, broken = {}, {}
local V = nil                   -- the view
local can_in, can_out = false, false
local msg, msg_until = nil, 0
local down = nil                -- where the finger went down
local held = false              -- a long press answered on hold; its up is ignored
local qr = nil
local ERR = nil
local settings = { orient = 'portrait', names = 'on' }
local marker = nil              -- { lon7, lat7, pans }: a found place, until the map is moved twice
local results, query, rpage = {}, '', 1
local ROW_H = 64
local overlay                   -- defined with the drawing (below)
local route = nil               -- { name, points, len, thin = { [z] = points } }
local list = nil                -- the list screen: { title, items = { {label, sub, fn, long} }, page, top = {..} }
local VERSION = '1.0.0'

------------------------------------------------------------------ helpers

local function now() return kit.now_ms() or 0 end
local function say(s)
  msg, msg_until = s, now() + MSG_MS
  -- no tick runs: a timer redraws the header once the message is due to go
  pcall(function() ctx:after(MSG_MS + 50, function() kit.refresh() end) end)
end
local function map_h() return H - HEAD - BAR end

local function sync_screen()
  local okw, w = pcall(function() return tonumber(ctx.screen.width) end)
  local okh, h = pcall(function() return tonumber(ctx.screen.height) end)
  W, H = okw and w or 480, okh and h or 800
  kit.W, kit.H = W, H
end

local function load_settings()
  local t = kit.kv(kit.read('settings.txt'))
  if t.orient == 'landscape' then settings.orient = 'landscape' end
  if t.names == 'off' then settings.names = 'off' end
end
local function save_settings() kit.write('settings.txt', 'orient=' .. settings.orient .. '\nnames=' .. settings.names) end

local function save_view()
  if V then kit.write('view.txt', V.z .. ' ' .. V.cx .. ' ' .. V.cy) end
end

local function update_limits()
  if not V then return end
  can_in, can_out = choose.limits(packs, V.z, V.cx, V.cy)
end

-- the pack under the centre of the screen
local function centre_pack()
  if not V then return nil end
  return choose.pick(packs, V.z, V.cx >> 8, V.cy >> 8)
end

local function load_packs()
  packs, broken = {}, {}
  local ok, list = pcall(function() return ctx.files:list() end)
  if not ok or type(list) ~= 'table' then return end
  for _, f in ipairs(list) do
    local n = tostring(f.name or '')
    if n:lower():match('%.map$') then
      local p, err = pack.open(n)
      if p then packs[#packs + 1] = p else broken[#broken + 1] = { name = n, err = err } end
    end
  end
  table.sort(packs, function(a, b) return a.area < b.area end)
end

-- a pack's view: its middle, at zoom 14 (or the nearest level it has); the first view is the
-- smallest pack's
local function first_view(p)
  p = p or packs[1]
  local b = p.meta.bounds or {}
  local lon = ((tonumber(b[1]) or 0) + (tonumber(b[3]) or 0)) / 2
  local lat = ((tonumber(b[2]) or 0) + (tonumber(b[4]) or 0)) / 2
  local z = math.max(p.zmin, math.min(p.zmax, 14))
  local x, y = geo.lonlat_px(z, math.floor(lon * 1e7), math.floor(lat * 1e7))
  return z, x, y
end

local function make_view(z, cx, cy)
  if V then V:release() end
  V = view.new(ctx, W, map_h())
  V.packs = packs
  V.overlay = overlay
  V:set(z, cx, cy)
  update_limits()
end

local function moved()
  update_limits()
  save_view()
end

-- the host turns the screen between callbacks, after set_orientation returns: whenever the screen's
-- size is not the one the view was made for, make the view again for it (map and buttons)
local resize_asked = false
local function size_changed()
  local okw, w = pcall(function() return tonumber(ctx.screen.width) end)
  local okh, h = pcall(function() return tonumber(ctx.screen.height) end)
  w, h = okw and w or W, okh and h or H
  return V ~= nil and (w ~= V.w or h - HEAD - BAR ~= V.h)
end
local function fit_screen()
  resize_asked = false
  sync_screen()
  if V and (V.w ~= W or V.h ~= map_h()) then make_view(V.z, V.cx, V.cy) end
end

-- what is drawn into the map layer over the tiles: the marker (and the route, in the menu's code)
-- the route's points as global pixels at zoom z, worked out once per zoom from fixed anchors (a new
-- one only past 1 degree), so every pan draws them at the same pixels as the tiles under them
local FAR = 10000000
local function route_px(z)
  local px = route.thin[z]
  if px then return px end
  px = {}
  local A
  for _, p in ipairs(gpx.thin(route.points, z)) do
    if not A or math.abs(p.lon7 - A.lon7) > FAR or math.abs(p.lat7 - A.lat7) > FAR then A = geo.anchor_ll(z, p.lon7, p.lat7) end
    local x, y = geo.to_px(A, p.lon7, p.lat7)
    px[#px + 1] = x; px[#px + 1] = y
  end
  route.thin[z] = px
  return px
end

-- the route as beads: a bead every STEP pixels along it from its start, as global pixels per zoom,
-- so a pan draws them at the same pixels (black on e-ink streets would hide a plain line; beads with
-- a white ring stand out). Distances use differences of integers only.
local STEP, CORE, RING = 10, 4, 6      -- close beads: the route stands out (the user, on the device)
local function route_dots(z)
  route.dots = route.dots or {}
  local d = route.dots[z]
  if d then return d end
  d = {}
  local px = route_px(z)
  local carry = 0                                  -- distance since the last bead
  if #px >= 2 then d[1] = px[1]; d[2] = px[2] end
  for i = 3, #px - 1, 2 do
    local x0, y0 = px[i - 2], px[i - 1]
    local dx, dy = px[i] - x0, px[i + 1] - y0
    local len = math.sqrt(dx * dx + dy * dy)
    local t = STEP - carry
    while t <= len do
      d[#d + 1] = x0 + math.floor(dx * t / len + 0.5); d[#d + 1] = y0 + math.floor(dy * t / len + 0.5)
      t = t + STEP
    end
    carry = len - (t - STEP)
  end
  route.dots[z] = d
  return d
end

local function draw_route(g, left, top)
  local d = route_dots(V.z)
  local vis = {}
  for i = 1, #d, 2 do
    local x, y = d[i] - left, d[i + 1] - top
    if x > -RING and x < V.w + RING and y > -RING and y < V.h + RING then vis[#vis + 1] = x; vis[#vis + 1] = y end
  end
  for i = 1, #vis, 2 do g:circle(vis[i], vis[i + 1], RING, { fill = true, color = 0 }) end    -- rings first,
  for i = 1, #vis, 2 do g:circle(vis[i], vis[i + 1], CORE, { fill = true, color = 15 }) end   -- then beads
end

-- the street names beside the route, level, each in a white box (Menu: Street names on or off)
local function draw_labels(g, left, top)
  if settings.names == 'off' or V.z < 15 or not route.labels or #route.labels == 0 then return end
  route.place = route.place or {}
  local f = kit.font('medium')
  local lh = kit.line_h('medium')
  local pl = route.place[V.z]
  if not pl then
    pl = labels.place(route_px(V.z), route.labels, V.z, function(s) return kit.width(f, s) end, lh)
    route.place[V.z] = pl
  end
  for _, p in ipairs(pl) do
    local x, y = p.x - left, p.y - top
    if x > -p.w and x < V.w and y > -p.h and y < V.h then
      g:rect(x, y, p.w, p.h, { fill = true, color = 0 })
      g:rect(x, y, p.w, p.h)
      g:text(x + 8, y + 2, route.labels[p.idx].name, { font = f, bold = true })
    end
  end
end

function overlay(g, left, top)
  if route then draw_route(g, left, top); draw_labels(g, left, top) end
  if not marker then return end
  local m = marker.px[V.z]
  if not m then local mx, my = geo.lonlat_px(V.z, marker.lon7, marker.lat7); m = { mx, my }; marker.px[V.z] = m end
  local x, y = m[1] - left, m[2] - top
  for d = -1, 1 do
    g:line(x - 14, y + d, x - 5, y + d); g:line(x + 5, y + d, x + 14, y + d)
    g:line(x + d, y - 14, x + d, y - 5); g:line(x + d, y + 5, x + d, y + 14)
  end
  g:rect(x - 3, y - 3, 7, 7)
end

local function after_pan()
  if marker then
    marker.pans = marker.pans + 1
    if marker.pans >= 2 then marker = nil; V:refresh() end
  end
end

-- go to a position at (about) zoom `want`: the nearest level some pack has there
local function jump(lon7, lat7, want, mark)
  local z = choose.nearest(packs, want, function(zz) return geo.lonlat_px(zz, lon7, lat7) end)
  if not z then say('Not in any map pack'); screen = 'map'; return false end
  marker = mark and { lon7 = lon7, lat7 = lat7, pans = 0, px = {} } or marker
  local x, y = geo.lonlat_px(z, lon7, lat7)
  screen = 'map'
  V:set(z, x, y)
  moved()
  return true
end

------------------------------------------------------------------ actions

local function zoom_in(px, py)
  if not can_in then say('No closer level here'); return end
  V:zoom(1, px, py)
  moved()
end
local function zoom_out(px, py)
  if not can_out then say('No wider level here'); return end
  V:zoom(-1, px, py)
  moved()
end

local function point_at(x, y)
  local A = geo.anchor(V.z, V.cx, V.cy)
  return geo.from_px(A, V:left() + x, V:top() + (y - HEAD))
end

local function ask(title, text, fn)
  pcall(function()
    ctx.input:text({ title = title, text = text or '', max_bytes = 120 }, function(c, s)
      if s then fn(s) end
      kit.refresh()
    end)
  end)
end

local function run_search(q)
  query = q
  results = names.search(packs, q, 60)
  rpage = 1
  screen = 'search'
end
local function open_search() ask('Search: a place, a street, a station', query, run_search) end

-- bookmarks.txt: name<TAB>lat7<TAB>lon7 a line
local function read_bookmarks()
  local out = {}
  for l in (kit.read('bookmarks.txt') or ''):gmatch('[^\n]+') do
    local n, la, lo = l:match('^(.-)\t(%-?%d+)\t(%-?%d+)$')
    if n then out[#out + 1] = { name = n, lat7 = tonumber(la), lon7 = tonumber(lo) } end
  end
  table.sort(out, function(a, b) return a.name:lower() < b.name:lower() end)
  return out
end
local function write_bookmarks(bs)
  local t = {}
  for _, b in ipairs(bs) do t[#t + 1] = (b.name:gsub('[\t\n]', ' ')) .. '\t' .. b.lat7 .. '\t' .. b.lon7 end
  kit.write('bookmarks.txt', table.concat(t, '\n') .. '\n')
end
local function add_bookmark(lat7, lon7)
  local bs = read_bookmarks()
  ask('A name for this bookmark', 'Bookmark ' .. (#bs + 1), function(name)
    if name == '' then return end
    bs[#bs + 1] = { name = name, lat7 = lat7, lon7 = lon7 }
    write_bookmarks(bs)
    say('Bookmark added')
  end)
end

local function long_press(x, y)
  local lon7, lat7 = point_at(x, y)
  local lines = { geo.fmt(lat7, lon7) }
  for _, l in ipairs(near.lines(packs, lon7, lat7, V.z)) do lines[#lines + 1] = l end   -- what is held: a street, a peak, a lake
  kit.show({ title = 'This point', lines = lines,
    rows = { { { 'Add bookmark here', function() kit.close(); add_bookmark(lat7, lon7) end } }, { { 'Close', function() kit.close() end } } },
    cancel = function() kit.close() end })
end

------------------------------------------------------------------ the menu and its lists

local open_menu
local function show_list(title, items, top)
  list = { title = title, items = items, page = 1, top = top or {} }
  screen = 'list'
end

local function same_bm(a, b) return a.name == b.name and a.lat7 == b.lat7 and a.lon7 == b.lon7 end
local function open_bookmarks()
  local items = {}
  for _, b in ipairs(read_bookmarks()) do
    items[#items + 1] = { b.name, geo.fmt(b.lat7, b.lon7), function() jump(b.lon7, b.lat7, math.max(V.z, 16), true) end,
      function()
        kit.show({ title = b.name, rows = {
          { { 'Rename', function()
            kit.close()
            ask('A new name', b.name, function(n)
              if n == '' then return end
              local bs = read_bookmarks()
              for _, o in ipairs(bs) do if same_bm(o, b) then o.name = n end end
              write_bookmarks(bs); open_bookmarks()
            end)
          end }, { 'Delete', function()
            kit.close()
            local keep = {}
            for _, o in ipairs(read_bookmarks()) do if not same_bm(o, b) then keep[#keep + 1] = o end end
            write_bookmarks(keep); open_bookmarks()
          end } },
          { { 'Close', function() kit.close() end } } }, cancel = function() kit.close() end })
      end }
  end
  if #items == 0 then items[1] = { 'No bookmarks yet', 'Long press the map: Add bookmark here.', nil } end
  show_list('Bookmarks', items)
end

-- the deepest level the whole route fits on the screen (and some pack has at its middle);
-- false when no pack has it
local function fit_route()
  if not route then return false end
  local a = route.points[1]
  local w, s, e, n = a.lon7, a.lat7, a.lon7, a.lat7
  for _, p in ipairs(route.points) do
    if p.lon7 < w then w = p.lon7 end
    if p.lon7 > e then e = p.lon7 end
    if p.lat7 < s then s = p.lat7 end
    if p.lat7 > n then n = p.lat7 end
  end
  local mlon, mlat = w // 2 + e // 2, s // 2 + n // 2
  for z = 19, 8, -1 do
    local x0, y0 = geo.lonlat_px(z, w, n)
    local x1, y1 = geo.lonlat_px(z, e, s)
    if x1 - x0 <= V.w - 40 and y1 - y0 <= V.h - 40 then
      local cx, cy = geo.lonlat_px(z, mlon, mlat)
      if choose.pick(packs, z, cx >> 8, cy >> 8) then screen = 'map'; V:set(z, cx, cy); moved(); return true end
    end
  end
  screen = 'map'
  if choose.nearest(packs, 8, function(zz) return geo.lonlat_px(zz, mlon, mlat) end) then return jump(mlon, mlat, 8, false) end
  return false
end

local function open_route(name)
  pcall(function() ctx.budget:extend() end)        -- up to 1 MB read and parsed in this callback
  local okz, size = pcall(function() return ctx.files:size(name) end)
  size = okz and tonumber(size) or 0
  local text = size > 0 and pack.span(name, 0, math.min(size, 1048576)) or ''
  local r, why = gpx.parse(text)
  if not r then say(name .. ': ' .. tostring(why)); screen = 'map'; return end
  route = { name = r.name or name, points = r.points, len = gpx.length_m(r.points), thin = {}, labels = r.labels or {} }
  if #route.labels == 0 then route.labels = labels.from_index(packs, r.points, 12) end   -- another app's GPX
  screen = 'map'
  if fit_route() then                              -- go to it: all of it on the screen
    say(kit.short(route.name, 18) .. ': ' .. gpx.length_text(route.len))
  else
    V:refresh()
    say('No map pack has this route')
  end
end

local function open_routes()
  local items, top = {}, {}
  if route then
    top = { { 'Fit route', function() fit_route() end }, { 'Hide route', function()
      route = nil; screen = 'map'; V:refresh()
    end } }
  end
  local ok, files = pcall(function() return ctx.files:list() end)
  for _, f in ipairs(ok and type(files) == 'table' and files or {}) do
    local n = tostring(f.name or '')
    if n:lower():match('%.gpx$') then items[#items + 1] = { n, nil, function() open_route(n) end } end
  end
  if #items == 0 then items[1] = { 'No routes yet', 'Copy GPX files into AppFiles/offlinemap/.', nil } end
  show_list('Routes' .. (route and (': ' .. kit.short(route.name, 16) .. ', ' .. gpx.length_text(route.len)) or ''), items, top)
end

local function go_to_coords()
  ask('Coordinates, like 41.0082, 28.9784', '', function(s)
    local lat7, lon7 = geo.parse_coords(s)
    screen = 'map'
    if not lat7 then
      kit.show({ title = 'Go to coordinates', lines = { tostring(lon7), 'For example 41.0082, 28.9784' },
        rows = { { { 'Close', function() kit.close() end } } }, cancel = function() kit.close() end })
      return
    end
    jump(lon7, lat7, math.max(V.z, 15), true)
  end)
end

local function size_text(n) return n < 1048576 and (((n + 512) // 1024) .. ' KB') or string.format('%.1f MB', n / 1048576) end
local function open_packs()
  local items = {}
  for _, p in ipairs(packs) do
    items[#items + 1] = { tostring(p.meta.name or p.name), 'z' .. p.zmin .. '-' .. p.zmax .. ', ' .. size_text(p.file_size) .. ', ' .. p.made,
      function()                                   -- go to the pack
        local z, x, y = first_view(p)
        screen = 'map'
        V:set(z, x, y)
        moved()
      end }
  end
  for _, b in ipairs(broken) do items[#items + 1] = { b.name, tostring(b.err), nil } end
  show_list('Map packs', items)
end

local function turn_screen()
  settings.orient = settings.orient == 'portrait' and 'landscape' or 'portrait'
  save_settings()
  pcall(function() ctx.screen:set_orientation(settings.orient) end)
  screen = 'map'
  fit_screen()                                     -- if the host turned it at once; else the next callback
end

local function open_about()
  if not qr then
    local okq, im = pcall(function() return ctx.qr:encode(TOOLS_URL, { size = 160 }) end)
    qr = okq and im or nil
  end
  local seen, attr = {}, {}
  for _, p in ipairs(packs) do
    local a = tostring(p.meta.attribution or '')
    if a ~= '' and not seen[a] then seen[a] = true; attr[#attr + 1] = a end
  end
  list = { title = 'About Offline Map ' .. VERSION, items = {}, page = 1, top = {}, about = attr }
  screen = 'about'
end

function open_menu()
  show_list('Menu', {
    { 'Bookmarks', nil, open_bookmarks },
    { 'Routes', nil, open_routes },
    { 'Go to coordinates', nil, go_to_coords },
    { 'Map packs', nil, open_packs },
    { 'Screen: ' .. settings.orient, nil, turn_screen },
    { 'Street names: ' .. settings.names, 'beside a route', function()
      settings.names = settings.names == 'on' and 'off' or 'on'
      save_settings()
      screen = 'map'
      V:refresh()
    end },
    { 'About', nil, open_about },
  })
end

local function all_missing()
  if not V then return false end
  local cols = ((V:left() + V.w - 1) >> 8) - (V:left() >> 8) + 1
  local rows = ((V:top() + V.h - 1) >> 8) - (V:top() >> 8) + 1
  return V.missing >= cols * rows
end

------------------------------------------------------------------ drawing

local BTNS = { '-', '+', 'Search', 'Menu' }
local function bar_rect(i)
  local bw = (W - 8 * 5) // 4
  return 8 + (i - 1) * (bw + 8), H - BAR + 6, bw, BAR - 12
end
local function packs_btn() return W // 2 - 90, HEAD + map_h() // 2 - 30, 180, 60 end

local function draw_header(gg)
  local p = centre_pack()
  local title = (now() < msg_until and msg) or (V and V.edge and 'Edge of the map') or (p and tostring(p.meta.name or p.name)) or ''
  local f = kit.font('small')
  local zs = 'z' .. V.z
  local m, px = geo.scale_bar(V.z, select(2, geo.from_px(geo.anchor(V.z, V.cx, V.cy), V.cx, V.cy)))
  local label = m >= 1000 and ((m // 1000) .. ' km') or (m .. ' m')
  local sx = W - 8 - px
  gg:line(sx, 24, W - 8, 24); gg:line(sx, 18, sx, 28); gg:line(W - 8, 18, W - 8, 28)
  gg:text(sx + (px - kit.width(f, label)) // 2, 2, label, { font = f })
  gg:text(sx - 12 - kit.width(f, zs), 6, zs, { font = f })
  gg:text(8, 6, kit.short(title, 26), { font = f })
  gg:line(0, HEAD - 1, W, HEAD - 1)
end

local function draw_bar(gg)
  gg:line(0, H - BAR, W, H - BAR)
  for i, label in ipairs(BTNS) do
    local x, y, w, h = bar_rect(i)
    local faded = (i == 1 and not can_out) or (i == 2 and not can_in)
    kit.button(gg, x, y, w, h, faded and ('(' .. label .. ')') or label, { line_width = faded and 1 or 2 })
  end
end

local function draw_start(gg)
  gg:text(24, 30, 'Offline Map', { font = kit.font('large') })
  local y = 80
  local text = {
    'A map without a connection, like a folding paper map. It has no live position: find places by name, '
      .. 'or type coordinates read off a phone.',
    'Make a map pack on the Tools page (scan the code), then copy it to AppFiles/offlinemap/ on the card. '
      .. 'GPX routes go in the same folder.',
  }
  for _, para in ipairs(text) do
    for _, l in ipairs(kit.wrap(para, 'small', W - 48)) do gg:text(24, y, l, { font = kit.font('small') }); y = y + 24 end
    y = y + 10
  end
  if qr then gg:image(qr, (W - (tonumber(qr.width) or 200)) // 2, y + 10) end
end

local function per_page() return (H - 70 - 70) // ROW_H end
local function result_rect(i) return 12, 60 + (i - 1) * ROW_H, W - 24, ROW_H - 6 end
local function search_btns() return { { 'New search', 12 }, { 'Map', W // 2 + 6 } } end
local function draw_search(gg)
  gg:text(12, 14, kit.short('Search: ' .. query, 34), { font = kit.font('medium') })
  gg:line(0, 50, W, 50)
  if #results == 0 then gg:text(12, 70, 'Nothing found in the map packs.', { font = kit.font('small') }) end
  local n = per_page()
  for i = 1, n do
    local e = results[(rpage - 1) * n + i]
    if not e then break end
    local x, y = result_rect(i)
    gg:text(x, y, kit.short(e.name, 30), { font = kit.font('medium') })
    gg:text(x, y + 30, (names.KIND[e.kind] or 'place') .. ', ' .. kit.short(tostring(e.pack.meta.name or e.pack.name), 28), { font = kit.font('small') })
  end
  local pages = math.max(1, (#results + n - 1) // n)
  if pages > 1 then gg:text(W - 90, H - 100, rpage .. ' / ' .. pages, { font = kit.font('small') }) end
  for _, b in ipairs(search_btns()) do kit.button(gg, b[2], H - 60, W // 2 - 18, 48, b[1]) end
end

local function tap_search(x, y)
  if y >= H - 60 then
    if x < W // 2 then open_search() else screen = 'map' end
    return
  end
  local n = per_page()
  for i = 1, n do
    local e = results[(rpage - 1) * n + i]
    local rx, ry, rw, rh = result_rect(i)
    if e and x >= rx and x < rx + rw and y >= ry and y < ry + rh then
      jump(e.lon7, e.lat7, names.ZOOM[e.kind] or 15, true)
      return
    end
  end
end

local LROW = 58
local function list_per_page() return (H - 60 - 70 - #list.top * LROW) // LROW end
local function list_row(i) return 12, 60 + #list.top * LROW + (i - 1) * LROW end
local function draw_list(gg)
  gg:text(12, 14, kit.short(list.title, 34), { font = kit.font('medium') })
  gg:line(0, 50, W, 50)
  for i, b in ipairs(list.top) do kit.button(gg, 12 + (i - 1) * (W // 2 - 6), 56, W // 2 - 18, LROW - 10, b[1]) end
  local n = list_per_page()
  for i = 1, n do
    local it = list.items[(list.page - 1) * n + i]
    if not it then break end
    local x, y = list_row(i)
    gg:text(x, y + 4, kit.short(it[1], 32), { font = kit.font('medium') })
    if it[2] then gg:text(x, y + 32, kit.short(it[2], 44), { font = kit.font('small') }) end
    gg:line(x, y + LROW - 2, W - 12, y + LROW - 2)
  end
  local pages = math.max(1, (#list.items + n - 1) // n)
  if pages > 1 then gg:text(W - 90, H - 96, list.page .. ' / ' .. pages, { font = kit.font('small') }) end
  kit.button(gg, 12, H - 60, W - 24, 48, 'Map')
end
local function draw_about(gg)
  gg:text(12, 14, list.title, { font = kit.font('medium') })
  gg:line(0, 50, W, 50)
  local y = 64
  local paras = { 'Make a map pack on the Tools page (scan the code) and copy it to AppFiles/offlinemap/. '
    .. 'GPX routes go in the same folder. There is no live position.', 'Map data:' }
  for _, a in ipairs(list.about) do paras[#paras + 1] = a end
  if #list.about == 0 then paras[#paras + 1] = '© OpenStreetMap contributors' end
  for _, p in ipairs(paras) do
    for _, l in ipairs(kit.wrap(p, 'small', W - 24)) do gg:text(12, y, l, { font = kit.font('small') }); y = y + 22 end
    y = y + 6
  end
  if qr then gg:image(qr, (W - (tonumber(qr.width) or 160)) // 2, y + 6) end
  kit.button(gg, 12, H - 60, W - 24, 48, 'Map')
end

local function list_hit(x, y)
  for i, b in ipairs(list.top) do
    local bx = 12 + (i - 1) * (W // 2 - 6)
    if x >= bx and x < bx + W // 2 - 18 and y >= 56 and y < 56 + LROW - 10 then return { b[1], nil, b[2] } end
  end
  local n = list_per_page()
  for i = 1, n do
    local it = list.items[(list.page - 1) * n + i]
    local _, ry = list_row(i)
    if it and y >= ry and y < ry + LROW then return it end
  end
end
local function tap_list(x, y)
  if y >= H - 60 then screen = 'map'; return end
  if screen == 'about' then return end
  local it = list_hit(x, y)
  if it and it[3] then it[3]() end
end

------------------------------------------------------------------ callbacks

function on_load()
  local ok, e = pcall(function()
    sync_screen()
    load_settings()
    if (W > H) ~= (settings.orient == 'landscape') then
      pcall(function() ctx.screen:set_orientation(settings.orient) end)
      sync_screen()
    end
    load_packs()
    if #packs == 0 then
      screen = 'start'
      local okq, im = pcall(function() return ctx.qr:encode(TOOLS_URL, { size = 200 }) end)
      qr = okq and im or nil
      return
    end
    local z, cx, cy = (kit.read('view.txt') or ''):match('^(%d+) (%-?%d+) (%-?%d+)')
    z, cx, cy = tonumber(z), tonumber(cx), tonumber(cy)
    if not z or z < 8 or z > 19 then z, cx, cy = first_view() end
    make_view(z, cx, cy)
    screen = 'map'
  end)
  if not ok then ERR = tostring(e) end
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    if size_changed() then                         -- the screen turned: make the view in a timer (not here)
      sync_screen()
      if not resize_asked then
        local ok, t = pcall(function() return ctx:after(1, function() fit_screen(); kit.refresh() end) end)   -- 1 ms: 0 is refused
        resize_asked = ok and t ~= nil
      end
      gg:text(W // 2 - 40, H // 2, 'Turning...', { font = kit.font('medium') })
      return
    end
    if screen == 'start' then draw_start(gg)
    elseif screen == 'search' then draw_search(gg)
    elseif screen == 'list' then draw_list(gg)
    elseif screen == 'about' then draw_about(gg)
    elseif screen == 'map' and V then
      V:draw(gg, 0, HEAD)
      draw_header(gg)
      draw_bar(gg)
      if all_missing() then
        local x, y, w, h = packs_btn()
        kit.button(gg, x, y, w, h, 'Map packs')
      end
    end
    if kit.modal() then kit.draw_modal(gg) end
    if ERR then gg:text(8, H - 24, 'ERR ' .. kit.short(ERR, 40), { font = kit.font('small') }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 24, 'ERR ' .. tostring(e):sub(1, 40)) end) end
end

local function inside(x, y, rx, ry, rw, rh) return x >= rx and x < rx + rw and y >= ry and y < ry + rh end

local function pointer_up(ev)
  local x, y = tonumber(ev.x) or 0, tonumber(ev.y) or 0
  if kit.modal() then kit.tap_modal(x, y); return end
  if screen == 'search' then tap_search(x, y); return end
  if screen == 'list' or screen == 'about' then tap_list(x, y); return end
  if screen ~= 'map' or not V then return end
  if y >= H - BAR then
    for i = 1, #BTNS do
      if inside(x, y, bar_rect(i)) then
        if i == 1 then zoom_out(V.w // 2, V.h // 2)
        elseif i == 2 then zoom_in(V.w // 2, V.h // 2)
        elseif i == 3 then open_search()
        else open_menu() end
      end
    end
    return
  end
  if y < HEAD then return end
  local dx = x - (tonumber(ev.down_x) or (down and down.x) or x)
  local dy = y - (tonumber(ev.down_y) or (down and down.y) or y)
  if math.abs(dx) > MOVE or math.abs(dy) > MOVE then
    V:pan(-dx, -dy)
    moved()
    after_pan()
  elseif ev.gesture == 'double_tap' then
    zoom_in(x, y - HEAD)
  elseif all_missing() and inside(x, y, packs_btn()) then
    open_packs()
  end
end

local function key(k)
  if screen == 'search' then
    local n = per_page()
    local pages = math.max(1, (#results + n - 1) // n)
    if k == 'right' or k == 'down' then rpage = math.min(pages, rpage + 1) elseif k == 'left' or k == 'up' then rpage = math.max(1, rpage - 1) end
    return
  end
  if screen == 'list' then
    local n = list_per_page()
    local pages = math.max(1, (#list.items + n - 1) // n)
    if k == 'right' or k == 'down' then list.page = math.min(pages, list.page + 1) elseif k == 'left' or k == 'up' then list.page = math.max(1, list.page - 1) end
    return
  end
  if screen ~= 'map' or not V then return end
  local hw, hh = V.w // 2, V.h // 2
  if k == 'left' then V:pan(-hw, 0) elseif k == 'right' then V:pan(hw, 0)
  elseif k == 'up' then V:pan(0, -hh) elseif k == 'down' then V:pan(0, hh) else return end
  moved()
  after_pan()
end

function on_input(c, ev)
  local handled = true
  local ok, e = pcall(function()
    if size_changed() then fit_screen() end
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' then
      if ev.phase == 'down' then down = { x = tonumber(ev.x) or 0, y = tonumber(ev.y) or 0 }; held = false
      elseif ev.phase == 'hold' and screen == 'list' and not kit.modal() then   -- the gesture comes only on up
        local it = list_hit(tonumber(ev.x) or 0, tonumber(ev.y) or 0)
        if it and it[4] then held = true; it[4]() end
      elseif ev.phase == 'hold' then
        if screen == 'map' and V and not kit.modal() and (tonumber(ev.y) or 0) >= HEAD and (tonumber(ev.y) or 0) < H - BAR then
          held = true
          long_press(tonumber(ev.x) or 0, tonumber(ev.y) or 0)
        end
      elseif ev.phase == 'up' then
        if held then held = false
        else pointer_up(ev) end
        down = nil
      end
    elseif ev.type == 'key' and ev.key == 'back' then
      -- Back acts on its release (the host reads only the up event's answer): close a box, leave a
      -- screen; on the map it is left to the host, which offers to exit
      if ev.phase ~= 'up' and ev.phase ~= nil then return end
      if kit.modal() then
        if kit.modal().cancel then kit.modal().cancel() else kit.close() end
      elseif screen ~= 'map' and screen ~= 'start' then screen = 'map'
      else handled = false end
    elseif ev.type == 'key' and kit.key_accepted(ev) then
      key(ev.key)
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return handled
end

function on_tick()
  if msg and now() >= msg_until then msg = nil; kit.refresh() end
end

if rawget(_G, '__TEST') then
  __TEST.api = {
    fold = fold.fold,
    geo = geo, pack = pack, choose = choose, view = view, names = names, gpx = gpx, labels = labels, near = near,
    state = function() return { screen = screen, z = V and V.z, cx = V and V.cx, cy = V and V.cy, modal = kit.modal(), marker = marker, route = route, vw = V and V.w } end,
    layer_ops = function() return V and V.layer.ops or {} end,
    clear_ops = function() V.layer.ops = {}; V.spare.ops = {} end,     -- the test stub's record
  }
end
